import{_ as s,a0 as i,w as p,s as c,I as e,x as n,a1 as t,A as d,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"人工智能教程（五）：Anaconda 以及更多概率論 | LCTT x X-CMD","titleTemplate":false,"description":"人工智能教程（五）：Anaconda 以及更多概率論 | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"人工智能教程（五）：Anaconda 以及更多概率論 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"人工智能教程（五）：Anaconda 以及更多概率論 | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20221228 AI- Anaconda and More on Probability","title":"人工智能教程（五）：Anaconda 以及更多概率論","tag":"202401","desc":""},"relativePath":"202401/20221228 AI- Anaconda and More on Probability.md","filePath":"[post].md"}'),l={name:"202401/20221228 AI- Anaconda and More on Probability.md"};function u(b,o,h,m,g,T){const a=i("Link");return p(),c("div",null,[o[26]||(o[26]=e("h1",{id:"人工智能教程-五-anaconda-以及更多概率論",tabindex:"-1"},[n("人工智能教程（五）：Anaconda 以及更多概率論 "),e("a",{class:"header-anchor",href:"#人工智能教程-五-anaconda-以及更多概率論","aria-label":"Permalink to “人工智能教程（五）：Anaconda 以及更多概率論”"},"​")],-1)),o[27]||(o[27]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202401/02/161712jyckozyocvbz1c8v.jpg",alt:""})],-1)),o[28]||(o[28]=e("blockquote",null,[e("p",null,"在本系列的第五篇文章中，我們將繼續介紹概率和統計中的概念。")],-1)),e("p",null,[o[1]||(o[1]=n("在本系列的 ",-1)),t(a,{href:"https://linux.cn/article-16485-1.html"},{default:d(()=>[...o[0]||(o[0]=[n("前一篇文章",-1)])]),_:1}),o[2]||(o[2]=n(" 中，我們首先介紹了使用 TensorFlow。它是一個非常強大的開發人工智能和機器學習應用程序的庫。然後我們討論了概率論的相關知識，為我們後面的討論打下基礎。在本系列的第五篇文章中，我們將繼續介紹概率和統計中的概念。",-1))]),o[29]||(o[29]=r('<p>在本文中我將首先介紹 Anaconda，一個用於科學計算的 Python 發行版。它對於開發人工智能、機器學習和數據科學的程序特別有用。稍後我們將介紹一個名為 Theano 的 Python 庫。但在此之前，讓我們下討論一下人工智能的未來。</p><p>在回顧和修訂之前的文章時，我發覺我偶爾對人工智能前景的懷疑語氣和在一些話題上毫不留情的誠實態度可能在無意中使部分讀者產生了消極情緒。</p><p>這促使我開始從金融角度研究人工智能和機器學習。我想確定涉足人工智能市場的公司類型，是否有重量級的公司大力參與其中？還是隻有一些初創公司在努力推動？這些公司未來會向人工智能市場投入多少資金？是幾百萬美元，幾十億美元還是幾萬億美元？</p><p>我通過於最近知名報紙上的的預測和數據來理解基於人工智能的經濟發展背後的複雜動態性。2020 年《福布斯》上的一篇文章就預測 2020 年企業在人工智能上投入的投入將達到 500 億美元的規模。這是一筆巨大的投資。《財富》雜誌上發表的一篇文章稱，風險投資者正將部分關注力從人工智能轉移到 Web3 和<ruby>去中心化金融<rt>decentralised finance</rt></ruby>（DeFi）等更新潮的領域上。但《華爾街日報》在 2022 年自信地預測，“大型科技公司正在花費數十億美元進行人工智能研究。投資者應該密切關注。”</p><p>印度《商業標準報》在 2022 年報道稱，87% 的印度公司將在未來 3 年將人工智能支出提高 10%。總的來説，人工智能的未來看起來是非常安全和光明的。 令人驚訝的是，除了亞馬遜、Meta（Facebook 的母公司）、Alphabet（谷歌的母公司）、微軟、IBM 等頂級科技巨頭在投資人工智能外，殼牌、強生、聯合利華、沃爾瑪等非 IT 科技類公司也在大舉投資人工智能。</p><p>很明顯眾多世界級大公司都認為人工智能將在不久的將來發揮重要作用。但是未來的變化和新趨勢是什麼呢？我通過新聞文章和採訪找到一些答案。在人工智能未來趨勢的背景下，經常提到的術語包括<ruby>負責任的人工智能<rt>Responsible AI</rt></ruby>、量子人工智能、人工智能物聯網、人工智能和倫理、自動機器學習等。我相信這些都是需要深入探討的話題，在上一篇文章中我們已經討論過人工智能和倫理，在後續的文章中我們將詳細討論一些其它的話題。</p><h3 id="anaconda-入門" tabindex="-1">Anaconda 入門 <a class="header-anchor" href="#anaconda-入門" aria-label="Permalink to “Anaconda 入門”">​</a></h3>',7)),e("p",null,[o[4]||(o[4]=n("現在讓我們討論人工智能的必要技術。Anaconda 是用於科學計算的 Python 和 R 語言的發行版。它極大地簡化了包管理過程。從本文開始，我們將在有需要時使用 Anaconda。第一步，讓我們安裝 Anaconda。訪問 ",-1)),t(a,{href:"https://www.anaconda.com/products/distribution#linux"},{default:d(()=>[...o[3]||(o[3]=[n("安裝程序下載頁面",-1)])]),_:1}),o[5]||(o[5]=n(" 下載最新版本的 Anaconda 發行版安裝程序。在撰寫本文時（2022 年 10 月），64 位處理器上最新的 Anaconda 安裝程序是 ",-1)),o[6]||(o[6]=e("code",null,"Anaconda3-2022.05-Linux-x86_64.sh",-1)),o[7]||(o[7]=n("。如果你下載了不同版本的安裝程序，將後面命令中的文件名換成你實際下載的安裝文件名就行。下載完成後需要檢查安裝程序的完整性。在安裝程序目錄中打開一個終端，運行以下命令：",-1))]),o[30]||(o[30]=r('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shasum -a 256 Anaconda3-2022.05-Linux-x86_64.sh</span></span></code></pre></div><p>終端上會輸出哈希值和文件名。我的輸出顯示是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a7c0afe862f6ea19a596801fc138bde0463abcbce1b753e8d5c474b506a2db2d Anaconda3-2022.05-Linux-x86_64.sh</span></span></code></pre></div>',3)),e("p",null,[o[9]||(o[9]=n("然後訪問 ",-1)),t(a,{href:"https://docs.anaconda.com/anaconda/install/hashes"},{default:d(()=>[...o[8]||(o[8]=[n("Anaconda 安裝程序哈希值頁面",-1)])]),_:1}),o[10]||(o[10]=n("，比對下載安裝文件的哈希值。如果哈希值匹配，説明下載文件完整無誤，否則請重新下載。然後在終端上執行以下命令開始安裝：",-1))]),o[31]||(o[31]=r('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash Anaconda3-2022.05-Linux-x86_64.sh</span></span></code></pre></div><p>按回車鍵後，向下滾動查看並接受用户協議。最後，輸入 <code>yes</code> 開始安裝。出現用户交互提示時，一般直接使用 Anaconda 的默認選項就行。現在 Anaconda 就安裝完成了。</p><p>默認情況下，Anaconda 會安裝 Conda。這是一個包管理器和環境管理系統。Anaconda 發行版會自動安裝超過 250 個軟件包，並可選擇安裝超過 7500 個額外的開源軟件包。而且使用 Anaconda 安裝的任何包或庫都可以在 Jupyter Notebook 中使用。在安裝新包的過程中， Anaconda 會自動處理它的依賴項的更新。</p><p>至此之後我們終於不用再擔心安裝軟件包和庫的問題了，可以繼續我們的人工智能和機器學習程序的開發。注意，Anaconda 只有一個命令列界面。好在我們的安裝項中包括 Anaconda Navigator。這是一個用於 Anaconda 的圖形用户界面。在終端上執行命令 <code>anaconda-navigator</code> 運行 Anaconda Navigator（圖 1）。我們馬上會通過例子看到它的強大功能。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/11/Figure-1-Anaconda-Navigator-.png" alt="圖 1：Anaconda Navigator"></p><h3 id="theano-介紹" tabindex="-1">Theano 介紹 <a class="header-anchor" href="#theano-介紹" aria-label="Permalink to “Theano 介紹”">​</a></h3><p>Theano 是一個用於數學表達式計算的優化編譯的 Python 庫。在 Anaconda Navigator 中安裝Theano 非常容易。打開 Anaconda Navigator 後點擊 “<ruby>環境<rt>Environments</rt></ruby>” 按鈕（圖 1 中用紅框標記）。在打開的窗口中會顯示當前安裝的所有軟件包的列表。在頂部的下拉列表中選擇“<ruby>尚未安裝<rt>Not installed</rt></ruby>”選項。向下滾動並找到 Theano，然後勾選左側的複選框。點擊窗口右下角的綠色 “<ruby>應用<rt>Apply</rt></ruby>” 按鈕。Anaconda 會在彈出菜單中顯示安裝 Theano 的所有依賴項。圖 2 是我安裝 Theano 時的彈出菜單。可以看到，除了 Theano 之外，還安裝了一個新的包，並修改了 8 個包。</p><p>想像一下，如果要手動安裝 Theano，這將是多麼麻煩。有了 Anaconda，我們只需要點幾個按鈕就行了。只需要等待一會兒，Theano 就安裝好了。現在我們可以在 Jupyter Notebook 中使用 Theano 了。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/11/Figure-2-Installation-of-Theano.png" alt="圖 2：安裝 Theano"></p><p>我們已經熟悉了用於符號計算的 Python 庫 SymPy，但 Theano 將符號計算提升到了一個新的水平。圖 3 是一個使用 Theano 的例子。第 1 行代碼導入 Theano。第 2 行導入 <code>theano.tensor</code> 並將其命名為 <code>T</code>。我們在介紹 TensorFlow 時已經介紹過<ruby>張量<rt>tensor</rt></ruby>了。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/11/Figure-3-Our-first-code-using-Theano-590x394.png" alt="圖 3：使用 Theano 的代碼例子"></p><p>在數學上，可以將張量看作多維數組。張量是 Theano 的關鍵數據結構之一，它可用於存儲和操作標量（數字）、向量（一維數組）、矩陣（二維數組）、張量（多維數組）等。在第 3 行中，從 Theano 導入了 <code>function()</code> 的函數。第 4 行導入名為 <code>pp()</code> 的 Theano 函數，該函數用於格式化打印。第 5 行創建了一個名為 <code>x</code> 的 <code>double</code> 類型的標量符號變量。你可能會在理解符號變量這個概念上遇到一些困難。這裏你可以把它看作是沒有綁定具體值的 <code>double</code> 類型的對象。類似地，第 6 行創建了另一個名為 <code>y</code> 的標量符號變量。第 7 行告訴 Python 解釋器，當符號變量 <code>x</code> 和 <code>y</code> 得到值時，將這些值相加並存儲在 <code>a</code> 裏面。</p><p>為了進一步解釋符號操作，仔細看第 8 行的輸出是 <code>(x+y)</code>。這表明兩個數字的實際相加還沒有發生。第 9 到 11 行類似地分別定義了符號減法、乘法和除法。你可以自己使用函數 <code>pp()</code> 來查找 <code>b</code>、<code>c</code> 和 <code>d</code> 的值。第 12 行非常關鍵。它使用 Theano 的 <code>function()</code> 函數定義了一個名為 <code>f()</code> 的新函數。 函數 <code>f()</code> 的輸入是 <code>x</code> 和 <code>y</code>，輸出是 <code>[a b c d]</code>。最後在第 13 行中，給函數 <code>f()</code> 提供了實際值來調用該函數。該操作的輸出也顯示在圖 3 中。我們很容易驗證所顯示的輸出是正確的。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/11/Figure-4-Manipulating-matrices-with-Theano.png" alt="圖 4：用 Theano 處理矩陣"></p><p>下面讓我們通過圖 4 的代碼來看看如何使用 Theano 創建和操作矩陣。需要注意的是，圖中我省略了導入代碼。如果你要直接運行圖 4 的代碼，需要自己添加上這幾行導入代碼（圖 3 中的前三行）。第 1 行創建了兩個符號矩陣 <code>x</code> 和 <code>y</code>。這裏我使用了<ruby>複數構造函數<rt>plural constructor</rt></ruby> <code>imatrices</code>，它可以同時構造多個矩陣。第 2 行到第 4 行分別對符號矩陣 <code>x</code> 和 <code>y</code> 執行符號加法、減法和乘法。這裏你可以使用 <code>print(pp(a))</code>、<code>print(pp(b))</code> 和 <code>print(pp(c))</code> 來幫助理解符號操作的性質。第 5 行創建了一個函數 <code>f()</code>，它的輸入是兩個符號矩陣 <code>x</code> 和 <code>y</code>，輸出是 <code>[a b c]</code>，它們分別表示符號加法、減法和乘法。最後，在第 6 行中，為函數 <code>f()</code> 提供實際的值來調用該函數。該操作的輸出也顯示在圖 4 中。很容易驗證所示的三個輸出矩陣是否正確。注意，除了標量和矩陣，張量還提供了向量、行、列類型張量的構造函數。Theano 暫時就介紹到這裏了，在討論概率和統計的進階話題時我們還會提到它。</p><h3 id="再來一點概率論" tabindex="-1">再來一點概率論 <a class="header-anchor" href="#再來一點概率論" aria-label="Permalink to “再來一點概率論”">​</a></h3><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/11/Figure-5-Arithmetic-mean-and-standard-deviation-590x164.png" alt="圖 5：算術平均值和標準偏差"></p><p>現在我們繼續討論概率論和統計。我在上一篇文章中我建議你仔細閲讀三篇維基百科文章，然後介紹了正態分佈。在我們開始開發人工智能和機器學習程序之前，有必要回顧一些概率論和統計的基本概念。我們首先要介紹的是 <ruby>算術平均值<rt>arithmetic mean</rt></ruby>和<ruby>標準差<rt>standard deviation</rt></ruby>。</p><p>算術平均值可以看作是一組數的平均值。標準差可以被認為是一組數的分散程度。如果標準差較小，則表示集合中的元素都接近平均值。相反，如果標準差很大，則表示集合的中的元素分佈在較大的範圍內。如何使用 Python 計算算術平均值和標準差呢？Python 中有一個名為 <code>statistics</code> 的模組，可用於求平均值和標準差。但專家用户認為這個模組太慢，因此我們選擇 NumPy。</p><p>圖 5 所示的代碼打印兩個列表 <code>C1</code> 和 <code>C2</code> 的平均值和標準差（我暫時隱藏了兩個列表的實際內容）。你能從這些值中看出什麼呢？目前它們對你來説只是一些數字而已。現在我告訴你，這些列表分別包含學校 A 和學校 B 的 6 名學生的數學考試成績（滿分 50 分，及格 20 分）。均值告訴我們，兩所學校的學生平均成績都較差，但學校 B 的成績略好於學校 A。標準差值告訴我們什麼呢？學校 B 的巨大的標準差值雖然隱藏在平均值之下，但卻清楚地反映了學校 B 的的教學失敗。為了進一步加深理解，我將給出兩個列表的值，<code>C1 =[20,22,20,22,22,20] </code>，<code>C2 =[18,16,17,16,15,48]</code>。這個例子清楚地告訴我們，我們需要更復雜的參數來處理問題的複雜性。概率和統計將提供更復雜的模型來描述複雜和混亂的數據。</p><p>隨機數生成是概率論的重要組成部分。但實際上我們只能生成偽隨機數。偽隨機數序列具有和真隨機數序列近似的性質。在圖 6 中我們介紹了幾個生成偽隨機數的函數。第 1 行導入 Python 的 <code>random</code> 包。第 2 行代碼生成兩個隨機數，並將它們存儲在名為 <code>new_list</code> 的列表中。其中函數 <code>random.random()</code> 生成隨機數，代碼 <code>new_list = [random.random() for i in range(2)]</code> 使用了 Python 的<ruby>列表推導<rt>list comprehension</rt></ruby>語法。第 3 行將此列表打印輸出。注意，每次執行代碼打印出的兩個隨機數會變化，並且連續兩次打印出相同數字的概率理論上為 0。圖 6 的第二個代碼單元中使用了 <code>random.choice()</code> 函數。這個函數從給定的選項中等概率地選擇數據。代碼片 <code>random.choice([&quot;Heads&quot;, &quot;Tails&quot;])</code> 將等概率地在“Heads”和“Tails”之間選擇。注意，該行代碼也使用了列表推導，它會連續執行 3 次選擇操作。從圖 6 的輸出可以看到，三次都選中了“Tails”。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/11/Figure-6-Pseudo-random-number-generation-590x168.png" alt="圖 6：偽隨機數生成"></p><p>現在，我們用一個簡單的例子來説明概率論中著名的<ruby>大數定理<rt>xxx</rt></ruby>。大數定理表明從大量試驗中獲得的結果的平均值應該接近期望值，並且隨着試驗次數的增加這個平均值會越來越接近期望值。我們都知道，投擲一個均勻的骰子得到數字 6 的概率是 1/6。我們用圖 7 中的 Python 代碼來模擬這個實驗。第 1 行導入 Python 的 <code>random</code> 包。第 2 行設置重複試驗的次數為 1000。第 3 行將計數器 <code>ct</code> 初始化為 0。第 4 行是一個循環，它將迭代 1000 次。第 5 行的 <code>random.randint(1, 6)</code> 隨機生成 1 到 6 之間的整數（包括 1 和 6）。然後檢查生成的數字是否等於 6；如果是，則轉到第 7 行，將計數器 <code>ct</code> 增加 1。循環迭代 1000 次後，第 8 行打印數字 6 出現的次數與總試驗次數之間的比例。圖 7 顯示該比例為 0.179，略高於期望值 1/6 = 0.1666…。這與期望值的差異還是比較大的。將第 2 行中 <code>n</code> 的值設置為 10000，再次運行代碼並觀察打印的輸出。很可能你會得到一個更接近期望值的數字（它也可能是一個小於期望值的數字）。不斷增加第 2 行中 <code>n</code> 的值，你將看到輸出越來越接近期望值。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/11/Figure-7-Illustrating-the-law-of-large-numbers-590x266.png" alt="圖 7：大數定理"></p><p>雖然大數定理的描述樸實簡單，但如果你瞭解到哪些數學家證明了大數定理或改進了原有的證明，你一定會大吃一驚的。他們包括卡爾達諾、雅各布·伯努利、丹尼爾·伯努利、泊松、切比雪夫、馬爾科夫、博雷爾、坎特利、科爾莫戈羅夫、欽欽等。這些都是各自領域的數學巨匠。</p><p>目前我們還沒有涵蓋概率的隨機變量、概率分佈等主題，它們對開發人工智能和機器學習程序是必不可少的。我們對概率和統計的討論仍處於初級階段，在下一篇文章中還會加強這些知識。與此同時，我們將重逢兩個老朋友，Pandas 和 TensorFlow。另外我們還將介紹一個與 TensorFlow 關係密切的庫 Keras。</p><p><em>（題圖：DA/ea8d9b6a-5282-41ad-a84f-3e3815e359fb）</em></p><hr>',28)),e("p",null,[o[12]||(o[12]=n("via: ",-1)),t(a,{href:"https://www.opensourceforu.com/2022/12/ai-anaconda-and-more-on-probability/"},{default:d(()=>[...o[11]||(o[11]=[n("https://www.opensourceforu.com/2022/12/ai-anaconda-and-more-on-probability/",-1)])]),_:1})]),e("p",null,[o[17]||(o[17]=n("作者：",-1)),t(a,{href:"https://www.opensourceforu.com/author/deepu-benson/"},{default:d(()=>[...o[13]||(o[13]=[n("Deepu Benson",-1)])]),_:1}),o[18]||(o[18]=n(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:d(()=>[...o[14]||(o[14]=[n("lujun9972",-1)])]),_:1}),o[19]||(o[19]=n(" 譯者：",-1)),t(a,{href:"https://github.com/toknow-gh"},{default:d(()=>[...o[15]||(o[15]=[n("toknow-gh",-1)])]),_:1}),o[20]||(o[20]=n(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:d(()=>[...o[16]||(o[16]=[n("wxy",-1)])]),_:1})]),e("p",null,[o[23]||(o[23]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...o[21]||(o[21]=[n("LCTT",-1)])]),_:1}),o[24]||(o[24]=n(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:d(()=>[...o[22]||(o[22]=[n("Linux中國",-1)])]),_:1}),o[25]||(o[25]=n(" 榮譽推出",-1))])])}const w=s(l,[["render",u]]);export{A as __pageData,w as default};
